DELETE FROM public.lessons;

INSERT INTO public.lessons (track_kind, track_slug, sector_slug, module_slug, lesson_slug, title, content_md) VALUES ('concurso', 'minint', 'policia-nacional', 'portugues', 'intro', 'Introdução e Conceitos Base', '## Introdução
Esta aula de **Introdução e Conceitos Base** faz parte do módulo de **Língua Portuguesa** para o curso de **Policia Nacional** no âmbito do **Ministério do Interior**. 
O domínio deste conteúdo é fundamental para o sucesso no exame de admissão e para a futura prática profissional.

## Conceitos fundamentais
- **Definição de Introdução e Conceitos Base:** Explicação técnica e enquadramento no sistema angolano.
- **Importância do Módulo:** Como o conteúdo de Língua Portuguesa se relaciona com as exigências da carreira.
- **Base Normativa:** Referências à legislação e regulamentos vigentes em Angola.

## Aprofundamento
O estudo de Introdução e Conceitos Base exige atenção aos detalhes técnicos e à aplicação prática. No contexto de Policia Nacional, é crucial compreender os procedimentos operacionais e a ética profissional.

## Exemplos resolvidos
1. **Caso Prático:** Análise de uma situação real em Policia Nacional.
   - *Resolução:* Aplicação direta dos conceitos de Língua Portuguesa.
2. **Questão de Exame:** Pergunta típica de concursos anteriores.
   - *Explicação:* Porquê esta é a resposta correta de acordo com a norma.

## Resumo
- Revisão dos pontos essenciais de Introdução e Conceitos Base.
- Destaque para os erros comuns em provas.
- Sugestão de leitura complementar.

## Glossário
- **Termo Técnico 1:** Significado no contexto de Ministério do Interior.
- **Termo Técnico 2:** Definição operacional para Policia Nacional.
');
