INSERT INTO public.lessons (track_kind, track_slug, sector_slug, module_slug, lesson_slug, title, content_md) VALUES ('concurso', 'minsa', 'tecnicos-diagnostico', 'portugues', 'intro', 'Introdução e Conceitos Base', '## Introdução
