INSERT INTO public.lessons (track_kind, track_slug, sector_slug, module_slug, lesson_slug, title, content_md) VALUES ('preparatorio', 'saude', 'medicina', 'especifico', 'intro', 'Introdução e Conceitos Base', '## Introdução
Esta aula de **Introdução e Conceitos Base** faz parte do módulo de **Conhecimentos Específicos** para o curso de **Medicina** no âmbito do **Ciências da Saúde**. 
O domínio deste conteúdo é fundamental para o sucesso no exame de admissão e para a futura prática profissional.

## Conceitos fundamentais
- **Definição de Introdução e Conceitos Base:** Explicação técnica e enquadramento no sistema angolano.
- **Importância do Módulo:** Como o conteúdo de Conhecimentos Específicos se relaciona com as exigências da carreira.
- **Base Normativa:** Referências à legislação e regulamentos vigentes em Angola.

## Aprofundamento
O estudo de Introdução e Conceitos Base exige atenção aos detalhes técnicos e à aplicação prática. No contexto de Medicina, é crucial compreender os procedimentos operacionais e a ética profissional.

## Exemplos resolvidos
1. **Caso Prático:** Análise de uma situação real em Medicina.
   - *Resolução:* Aplicação direta dos conceitos de Conhecimentos Específicos.
2. **Questão de Exame:** Pergunta típica de concursos anteriores.
   - *Explicação:* Porquê esta é a resposta correta de acordo com a norma.

